def min_val(lst):
    return min(x for x in lst if isinstance(x, (int, float)))

import unittest

class TestMinVal(unittest.TestCase):
    def test_min_val(self):
        self.assertEqual(min_val(['Python', 3, 2, 4, 5, 'version']), 2)
        self.assertEqual(min_val(['Python', 15, 20, 25]), 15)
        self.assertEqual(min_val(['Python', 30, 20, 40, 50, 'version']), 20)

if __name__ == '__main__':
    unittest.main()
